import { ChevronRight } from 'lucide-react'

import { cx } from '~/lib/cx'
import styles from './json-viewer.module.scss'

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

function Primitive({ value }: { value: unknown }) {
  if (value === null) return <span className={styles.null}>null</span>
  if (typeof value === 'string')
    return <span className={styles.string}>&quot;{value}&quot;</span>
  if (typeof value === 'number')
    return <span className={styles.number}>{String(value)}</span>
  if (typeof value === 'boolean')
    return <span className={styles.boolean}>{String(value)}</span>
  return <span className={styles.other}>{String(value)}</span>
}

function JsonNode({
  name,
  value,
  depth,
  defaultExpandDepth,
}: {
  name?: string
  value: unknown
  depth: number
  defaultExpandDepth: number
}) {
  if (!isRecord(value) && !Array.isArray(value)) {
    return (
      <div
        className={styles.row}
        style={{ paddingLeft: depth * 14 + 16 }}
      >
        {name ? <span className={styles.key}>{name}:</span> : null}
        <Primitive value={value} />
      </div>
    )
  }

  const entries = Array.isArray(value)
    ? value.map((item, index) => [String(index), item] as const)
    : Object.entries(value)
  const open = depth < defaultExpandDepth

  return (
    <details open={open} className={styles.details}>
      <summary
        className={styles.summary}
        style={{ paddingLeft: depth * 14 + 4 }}
      >
        <ChevronRight className={styles.chevron} aria-hidden />
        {name ? <span className={styles.key}>{name}:</span> : null}
        <span className={styles.count}>
          {Array.isArray(value) ? `[${entries.length}]` : `{${entries.length}}`}
        </span>
      </summary>
      <div>
        {entries.map(([key, child]) => (
          <JsonNode
            key={key}
            name={key}
            value={child}
            depth={depth + 1}
            defaultExpandDepth={defaultExpandDepth}
          />
        ))}
      </div>
    </details>
  )
}

export interface JsonViewerProps {
  data: unknown
  label?: string
  defaultExpandDepth?: number
  className?: string
}

export function JsonViewer({
  data,
  label = 'JSON data',
  defaultExpandDepth = 2,
  className,
}: JsonViewerProps) {
  let safe: unknown = data
  try {
    JSON.stringify(data)
  } catch {
    safe = '[Circular or non-serializable value]'
  }

  return (
    <div
      role="group"
      aria-label={label}
      className={cx(styles.root, className)}
    >
      <JsonNode value={safe} depth={0} defaultExpandDepth={defaultExpandDepth} />
    </div>
  )
}

@use 'styles' as vz;

$mono-font-stack:
  ui-monospace,
  'SF Mono',
  'SFMono-Regular',
  'Menlo',
  'Monaco',
  'Consolas',
  'Liberation Mono',
  monospace;

.root {
  max-height: 20rem;
  overflow: auto;
  padding: vz.space(2);
  border: 1px solid vz.color('border');
  border-radius: vz.radius('xl');
  background: vz.color('card');
  font-family: $mono-font-stack;

  @include vz.scrollbar;
}

.row {
  display: flex;
  gap: vz.space(1.5);
  padding-block: vz.space(0.5);
  font-size: vz.font-size('xs');
  line-height: 1.5;
}

.details {
  font-size: vz.font-size('xs');
}

.summary {
  display: flex;
  align-items: center;
  gap: vz.space(1);
  padding-block: vz.space(0.5);
  border-radius: vz.radius('xs');
  font-size: vz.font-size('xs');
  line-height: 1.5;
  list-style: none;
  cursor: pointer;

  @include vz.hover {
    background: vz.color('accent', 0.5);
  }

  @include vz.focus-ring(2px, 2px, 0.6);

  &::-webkit-details-marker {
    display: none;
  }
}

.details[open] .chevron {
  transform: rotate(90deg);
}

.chevron {
  flex: none;
  width: 0.75rem;
  height: 0.75rem;
  color: vz.color('muted-foreground');
  transition: transform vz.duration('fast') vz.ease('out');
}

.key {
  color: vz.color('foreground', 0.8);
}

.count {
  color: vz.color('muted-foreground');
}

.null {
  color: vz.color('muted-foreground');
}

.string {
  color: vz.color('success');
  overflow-wrap: anywhere;
}

.number {
  color: vz.color('info');
}

.boolean {
  color: vz.color('primary');
}

.other {
  color: vz.color('muted-foreground');
}
